-- 0049: General Science batch 9 — chapters 916, 917, 918, 920
-- Each chapter: 4 govt_technical, 4 govt_basic, 1 shared svg (level_id null). 9 atoms per chapter.

with src as (
  select v.chapter_id, v.level_id, v.atom_key, v.atom_type, v.atom_order, v.title, v.body::jsonb as body
  from (values
  (916,'govt_technical','gen-concept','concept',1,'आनुवंशिकी और DNA — SSC JE / RRB JE',$j${"note":"परीक्षा में DNA की संरचना, जीन और क्रोमोसोम की संख्या अक्सर पूछी जाती है।","text":"DNA एक द्विकुंडलित (double helix) अणु है, जिसमें नाइट्रोजन क्षारक (A, T, G, C) होते हैं। A सदैव T से और G सदैव C से जुड़ता है। जीन DNA का वह खंड है जो किसी गुण को नियंत्रित करता है। मनुष्य में 46 क्रोमोसोम (23 जोड़े) होते हैं।"}$j$),
  (916,'govt_technical','gen-formula','formula',2,'क्षारक जोड़ी नियम',$j${"formula":"A — T · G — C","explanation":"चारगैफ नियम: A = T और G = C की मात्रा समान होती है"}$j$),
  (916,'govt_technical','gen-example','example',3,'Numerical (JE style)',$j${"question":"यदि DNA के एक स्ट्रैंड में A = 20% है, तो दूसरे स्ट्रैंड में T का प्रतिशत कितना होगा?","solution":"A सदैव T से जुड़ता है, इसलिए T = A = 20%","answer":"20%"}$j$),
  (916,'govt_technical','gen-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"DNA में कौन सा क्षारक युग्म सही है?","options":["A–T","A–G","T–C","G–T"],"answer":0,"explanation":"DNA में A सदैव T से और G सदैव C से जुड़ता है।"},{"q":"मनुष्य की कोशिका में कुल क्रोमोसोम कितने होते हैं?","options":["46","23","48","44"],"answer":0,"explanation":"मनुष्य में 23 जोड़े, यानी कुल 46 क्रोमोसोम होते हैं।"}]}$j$),
  (916,'govt_basic','gen-concept','concept',1,'DNA और जीन',$j${"note":"परीक्षा में DNA का आकार और जीन का कार्य पूछा जाता है।","text":"DNA वह अणु है जिसमें आनुवंशिक जानकारी होती है। यह माता-पिता से संतान में जाता है। जीन DNA का वह भाग है जो किसी विशेष गुण (जैसे आँख का रंग) को नियंत्रित करता है।"}$j$),
  (916,'govt_basic','gen-formula','formula',2,'DNA की संरचना',$j${"formula":"DNA = द्विकुंडलित संरचना (double helix)","explanation":"वाटसन और क्रिक ने DNA की द्विकुंडलित संरचना का मॉडल दिया"}$j$),
  (916,'govt_basic','gen-example','example',3,'उदाहरण',$j${"question":"संतान में माता-पिता के गुण किसके द्वारा जाते हैं?","solution":"गुण जीन के द्वारा जाते हैं, जो DNA के खंड होते हैं","answer":"जीन (DNA)"}$j$),
  (916,'govt_basic','gen-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"DNA की संरचना का मॉडल किन वैज्ञानिकों ने दिया?","options":["वाटसन और क्रिक","मेंडल","डार्विन","पास्चर"],"answer":0,"explanation":"वाटसन और क्रिक ने 1953 में DNA की द्विकुंडलित संरचना प्रस्तुत की।"},{"q":"आनुवंशिक गुण किसमें संग्रहित होते हैं?","options":["DNA","RBC","प्लाज्मा","ऊतक"],"answer":0,"explanation":"आनुवंशिक जानकारी DNA में होती है।"}]}$j$),
  (916,null,'gen-diagram','svg',5,'DNA द्विकुंडली',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><path d='M60 10 Q90 35 60 60 Q30 85 60 110' stroke='#14b8a6' stroke-width='4' fill='none'/><path d='M100 10 Q70 35 100 60 Q130 85 100 110' stroke='#f59e0b' stroke-width='4' fill='none'/><text x='200' y='60' font-size='12' fill='#0f172a'>द्विकुंडलित DNA</text></svg>","caption":"DNA दो लड़ियों से बनी द्विकुंडलित संरचना है"}$j$),
  (917,'govt_technical','hered-concept','concept',1,'आनुवंशिकता और विकास — SSC JE / RRB JE',$j${"note":"परीक्षा में मेंडल के नियम, प्रभावी और अप्रभावी लक्षण और प्राकृतिक वरण अक्सर पूछे जाते हैं।","text":"मेंडल ने मटर पर प्रयोग करके आनुवंशिकता के मूल नियम दिए। प्रभावी (dominant) लक्षण संतान में प्रकट होता है, जबकि अप्रभावी (recessive) लक्षण केवल दोनों जीनों के अप्रभावी होने पर प्रकट होता है। डार्विन का प्राकृतिक वरण बताता है कि वातावरण के अनुकूल जीव जीवित रहकर संतति छोड़ते हैं।"}$j$),
  (917,'govt_technical','hered-formula','formula',2,'मेंडल का F₂ अनुपात',$j${"formula":"F₂ पीढ़ी में फीनोटाइप अनुपात = 3 : 1 (प्रभावी : अप्रभावी)","explanation":"जीनोटाइप अनुपात 1 : 2 : 1 होता है"}$j$),
  (917,'govt_technical','hered-example','example',3,'Numerical (JE style)',$j${"question":"मेंडल के एकसंकर संकरण में F₂ पीढ़ी में अप्रभावी लक्षण वाले पौधों का अनुपात कितना होता है?","solution":"F₂ में फीनोटाइप अनुपात 3:1 है, इसलिए अप्रभावी = 1 भाग (4 में से)","answer":"1/4 (25%)"}$j$),
  (917,'govt_technical','hered-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"मेंडल ने आनुवंशिकता का अध्ययन किस पौधे पर किया?","options":["मटर","गेहूँ","चावल","आम"],"answer":0,"explanation":"मेंडल ने मटर (Pisum sativum) पर प्रयोग किए।"},{"q":"प्राकृतिक वरण का सिद्धांत किसने दिया?","options":["डार्विन","मेंडल","लैमार्क","वाटसन"],"answer":0,"explanation":"चार्ल्स डार्विन ने प्राकृतिक वरण का सिद्धांत दिया।"}]}$j$),
  (917,'govt_basic','hered-concept','concept',1,'आनुवंशिकता और विकास',$j${"note":"परीक्षा में मेंडल, डार्विन और जीवाश्म पर प्रश्न आते हैं।","text":"माता-पिता के गुण संतान में जाना आनुवंशिकता है। जीवों में समय के साथ होने वाला क्रमिक परिवर्तन विकास (evolution) कहलाता है। जीवाश्म (fossils) विकास के प्रमाण हैं।"}$j$),
  (917,'govt_basic','hered-formula','formula',2,'विकास के प्रमाण',$j${"formula":"जीवाश्म + तुलनात्मक शरीर रचना + भ्रूण विज्ञान = विकास के प्रमाण","explanation":"समजात अंग (homologous organs) विकास के प्रमाण हैं"}$j$),
  (917,'govt_basic','hered-example','example',3,'उदाहरण',$j${"question":"व्हेल और मनुष्य की भुजाओं की हड्डियों की बनावट समान होना किस बात का प्रमाण है?","solution":"समान हड्डी रचना समजात अंगों का उदाहरण है, जो विकास का प्रमाण है","answer":"समजात अंग (विकास का प्रमाण)"}$j$),
  (917,'govt_basic','hered-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"विकास के सबसे प्रत्यक्ष प्रमाण कौन से हैं?","options":["जीवाश्म","रक्त","पेशी","बीज"],"answer":0,"explanation":"जीवाश्म पिछले युगों के जीवों के अवशेष हैं और विकास के प्रत्यक्ष प्रमाण हैं।"},{"q":"गुणों का माता-पिता से संतान में जाना क्या कहलाता है?","options":["आनुवंशिकता","वाष्पोत्सर्जन","प्रकाश संश्लेषण","उत्सर्जन"],"answer":0,"explanation":"गुणों के संचरण को आनुवंशिकता कहते हैं।"}]}$j$),
  (917,null,'hered-diagram','svg',5,'मेंडल का संकरण',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='20' y='20' width='80' height='30' fill='#86efac' rx='6'/><text x='60' y='39' text-anchor='middle' font-size='11' fill='#0f172a'>F₁ (प्रभावी)</text><rect x='130' y='20' width='80' height='30' fill='#fde047' rx='6'/><text x='170' y='39' text-anchor='middle' font-size='11' fill='#0f172a'>F₂: 3 : 1</text><line x1='100' y1='35' x2='130' y2='35' stroke='#64748b' stroke-width='2'/><text x='150' y='90' text-anchor='middle' font-size='11' fill='#64748b'>F₂ में फीनोटाइप अनुपात</text></svg>","caption":"F₁ से F₂ पीढ़ी में 3:1 फीनोटाइप अनुपात"}$j$),
  (918,'govt_technical','dis-concept','concept',1,'रोग और प्रतिरक्षा — SSC JE / RRB JE',$j${"note":"परीक्षा में रोगों के कारक (जीवाणु, विषाणु), वाहक और टीकाकरण पर प्रश्न अक्सर पूछे जाते हैं।","text":"रोग शरीर के कार्य में बाधा डालते हैं। संक्रामक रोग रोगाणुओं (जीवाणु, विषाणु, कवक, प्रोटोज़ोआ) से फैलते हैं, जबकि असंक्रामक रोग (जैसे मधुमेह) संक्रमण से नहीं फैलते। शरीर की प्रतिरक्षा (immunity) रोगाणुओं से बचाती है। टीका (vaccine) प्रतिरक्षा विकसित करता है।"}$j$),
  (918,'govt_technical','dis-formula','formula',2,'रोग और रोगाणु',$j${"formula":"मलेरिया → प्रोटोज़ोआ (प्लाज्मोडियम) · टाइफाइड → जीवाणु (साल्मोनेला) · AIDS → विषाणु (HIV)","explanation":"मलेरिया का वाहक मादा एनोफिलीज़ मच्छर है"}$j$),
  (918,'govt_technical','dis-example','example',3,'Numerical (JE style)',$j${"question":"मलेरिया किस रोगाणु से होता है और उसका वाहक कौन सा है?","solution":"मलेरिया प्लाज्मोडियम नामक प्रोटोज़ोआ से होता है, और इसका वाहक मादा एनोफिलीज़ मच्छर है","answer":"प्लाज्मोडियम; मादा एनोफिलीज़"}$j$),
  (918,'govt_technical','dis-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"AIDS किस रोगाणु से होता है?","options":["HIV विषाणु","जीवाणु","कवक","प्रोटोज़ोआ"],"answer":0,"explanation":"AIDS HIV विषाणु से होता है, जो प्रतिरक्षा तंत्र को कमजोर करता है।"},{"q":"पोलियो का टीका किस प्रकार की प्रतिरक्षा देता है?","options":["सक्रिय (active) प्रतिरक्षा","निष्क्रिय प्रतिरक्षा","जन्मजात","कोई नहीं"],"answer":0,"explanation":"टीका शरीर में रोगाणु के कमजोर रूप से सक्रिय प्रतिरक्षा विकसित करता है।"}]}$j$),
  (918,'govt_basic','dis-concept','concept',1,'रोग',$j${"note":"परीक्षा में संक्रामक और असंक्रामक रोगों का अंतर और टीकों का महत्व पूछा जाता है।","text":"कुछ रोग रोगाणुओं से फैलते हैं, जिन्हें संक्रामक रोग कहते हैं (जैसे टीबी, हैजा)। कुछ रोग संक्रमण से नहीं फैलते, जैसे मधुमेह। टीकाकरण से हम रोगों से बचते हैं।"}$j$),
  (918,'govt_basic','dis-formula','formula',2,'रोग और कारण',$j${"formula":"टीबी → जीवाणु (माइकोबैक्टीरियम) · हैजा → जीवाणु (विब्रियो) · खसरा → विषाणु","explanation":"ये सामान्य रूप से परीक्षा में पूछे जाने वाले संबंध हैं"}$j$),
  (918,'govt_basic','dis-example','example',3,'उदाहरण',$j${"question":"टीबी किसके कारण होता है?","solution":"टीबी माइकोबैक्टीरियम ट्यूबरकुलोसिस नामक जीवाणु से होता है","answer":"जीवाणु"}$j$),
  (918,'govt_basic','dis-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"इनमें से कौन सा असंक्रामक रोग है?","options":["मधुमेह","मलेरिया","हैजा","खसरा"],"answer":0,"explanation":"मधुमेह संक्रमण से नहीं फैलता, इसलिए यह असंक्रामक रोग है।"},{"q":"टीका किसलिए दिया जाता है?","options":["रोग से बचाव के लिए प्रतिरक्षा देने हेतु","बुखार उतारने के लिए","भूख बढ़ाने के लिए","नींद लाने के लिए"],"answer":0,"explanation":"टीका प्रतिरक्षा विकसित करके रोग से बचाव करता है।"}]}$j$),
  (918,null,'dis-diagram','svg',5,'रोग के वाहक',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='20' y='40' width='80' height='40' fill='#fde047' rx='6'/><text x='60' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>मच्छर (वाहक)</text><rect x='200' y='40' width='80' height='40' fill='#fca5a5' rx='6'/><text x='240' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>मनुष्य</text><line x1='100' y1='60' x2='200' y2='60' stroke='#64748b' stroke-width='3'/><text x='150' y='50' text-anchor='middle' font-size='10' fill='#64748b'>काटने से</text></svg>","caption":"मच्छर के काटने से मलेरिया जैसे रोग फैलते हैं"}$j$),
  (920,'govt_technical','env-concept','concept',1,'पर्यावरण और पारिस्थितिकी — SSC JE / RRB JE',$j${"note":"परीक्षा में खाद्य श्रृंखला, ऊर्जा का प्रवाह (10% नियम) और प्रदूषण के प्रकार अक्सर पूछे जाते हैं।","text":"पारिस्थितिकी तंत्र में उत्पादक, उपभोक्ता और अपघटक होते हैं। ऊर्जा एक दिशा में बहती है और प्रत्येक पोषण स्तर पर लगभग 10% ऊर्जा आगे जाती है (10% नियम)। जैव आवर्धन (biomagnification) में विषैले पदार्थ खाद्य श्रृंखला में ऊपर जाकर सांद्रित होते हैं।"}$j$),
  (920,'govt_technical','env-formula','formula',2,'ऊर्जा का प्रवाह',$j${"formula":"उत्पादक → प्राथमिक उपभोक्ता → द्वितीयक उपभोक्ता (ऊर्जा ~10% प्रति स्तर)","explanation":"अधिकांश ऊर्जा ऊष्मा के रूप में नष्ट होती है"}$j$),
  (920,'govt_technical','env-example','example',3,'Numerical (JE style)',$j${"question":"यदि उत्पादक में 10000 J ऊर्जा है, तो 10% नियम से द्वितीयक उपभोक्ता तक लगभग कितनी ऊर्जा पहुँचेगी?","solution":"प्राथमिक उपभोक्ता = 10% × 10000 = 1000 J; द्वितीयक उपभोक्ता = 10% × 1000 = 100 J","answer":"100 J"}$j$),
  (920,'govt_technical','env-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"पारिस्थितिकी तंत्र में ऊर्जा का प्रवाह किस प्रकार होता है?","options":["एक दिशा में","दो दिशाओं में","चक्रीय","कोई नहीं"],"answer":0,"explanation":"ऊर्जा एक दिशा में बहती है और अंत में ऊष्मा के रूप में नष्ट होती है।"},{"q":"जैव आवर्धन (biomagnification) किसका उदाहरण है?","options":["DDT का खाद्य श्रृंखला में सांद्रण","जल चक्र","प्रकाश संश्लेषण","श्वसन"],"answer":0,"explanation":"DDT जैसे विषैले पदार्थ खाद्य श्रृंखला में ऊपर सांद्रित होते हैं।"}]}$j$),
  (920,'govt_basic','env-concept','concept',1,'पर्यावरण',$j${"note":"परीक्षा में पर्यावरण प्रदूषण और उसके प्रकार पूछे जाते हैं।","text":"पर्यावरण में जीवित और निर्जीव दोनों घटक आते हैं। पारिस्थितिकी तंत्र में जीव एक दूसरे पर निर्भर रहते हैं। मानव गतिविधियों से वायु, जल और ध्वनि प्रदूषण बढ़ता है।"}$j$),
  (920,'govt_basic','env-formula','formula',2,'प्रदूषण के प्रकार',$j${"formula":"वायु प्रदूषण · जल प्रदूषण · ध्वनि प्रदूषण · मृदा प्रदूषण","explanation":"CO₂ और SO₂ वायु प्रदूषक हैं; ग्रीनहाउस गैसें जलवायु परिवर्तन बढ़ाती हैं"}$j$),
  (920,'govt_basic','env-example','example',3,'उदाहरण',$j${"question":"ओजोन परत को किस गैस से हानि होती है?","solution":"CFC (क्लोरोफ्लोरोकार्बन) ओजोन परत को नष्ट करती है","answer":"CFC (क्लोरोफ्लोरोकार्बन)"}$j$),
  (920,'govt_basic','env-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"खाद्य श्रृंखला में उत्पादक कौन होते हैं?","options":["हरे पौधे","शेर","मनुष्य","मेंढक"],"answer":0,"explanation":"हरे पौधे प्रकाश संश्लेषण से अपना भोजन बनाते हैं, इसलिए वे उत्पादक हैं।"},{"q":"ग्रीनहाउस गैस का उदाहरण कौन सा है?","options":["CO₂","N₂","O₂ (शुद्ध)","He"],"answer":0,"explanation":"CO₂ ऊष्मा को रोककर ग्रीनहाउस प्रभाव बढ़ाती है।"}]}$j$),
  (920,null,'env-diagram','svg',5,'खाद्य श्रृंखला',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><g font-size='11' fill='#0f172a' text-anchor='middle'><rect x='10' y='45' width='60' height='30' fill='#86efac' rx='4'/><text x='40' y='64'>पौधा</text><rect x='90' y='45' width='60' height='30' fill='#fde047' rx='4'/><text x='120' y='64'>कीट</text><rect x='170' y='45' width='60' height='30' fill='#fdba74' rx='4'/><text x='200' y='64'>मेंढक</text><rect x='240' y='45' width='50' height='30' fill='#fca5a5' rx='4'/><text x='265' y='64'>साँप</text></g><text x='150' y='112' text-anchor='middle' fill='#64748b' font-size='11'>ऊर्जा ~10% प्रति स्तर</text></svg>","caption":"एक सरल खाद्य श्रृंखला"}$j$)
  ) as v(chapter_id, level_id, atom_key, atom_type, atom_order, title, body)
)
insert into mtb.atoms (chapter_id, level_id, atom_key, atom_type, atom_order, title, body, lang, exam_tags, subject_tag, difficulty, content_hash)
select s.chapter_id, s.level_id, s.atom_key, s.atom_type, s.atom_order, s.title, s.body, 'hi',
  case
    when s.level_id = 'govt_technical' then array['rrb-je-cbt1','rrb-je-cbt2','ssc-je-paper1']::text[]
    when s.level_id = 'govt_basic' then array['rrb-ntpc-graduate-cbt-1','rrb-ntpc-graduate-cbt-2','rrb-ntpc-ug-cbt-1','rrb-ntpc-ug-cbt-2']::text[]
    else '{}'::text[]
  end,
  'general-science', 'medium', md5(s.body::text)
from src s
on conflict do nothing;
